// Actual C2 runtime-probe function; synthetic storage/provider/audit boundaries only.
import assert from 'node:assert/strict';import {createHash} from 'node:crypto';
import {readFileSync,writeFileSync,readdirSync} from 'node:fs';import path from 'node:path';import {pathToFileURL} from 'node:url';
const root=process.env.PLUR1BUS_ENGINE_SRC;assert.ok(root);assert.equal(process.version,'v24.21.0');
const source=JSON.parse(readFileSync(new URL('./reembedding-sources.json',import.meta.url),'utf8'));const paths=[];
function walk(dir){for(const e of readdirSync(dir,{withFileTypes:true})){const p=path.join(dir,e.name);if(e.isDirectory())walk(p);else if(e.name.endsWith('.js'))paths.push(p);}}
walk(path.join(root,'engine'));walk(path.join(root,'lib'));const hash=createHash('sha256');for(const p of paths.sort()){hash.update(`${path.relative(root,p)}\0`);hash.update(readFileSync(p));hash.update('\0');}assert.equal(hash.digest('hex'),source.treeSha256);
const {createGenerationRuntimeProbe}=await import(pathToFileURL(path.join(root,'lib/reembedding/runtime-probe.js')));
const cases=[{name:'happy'},{name:'selection-drift',active:'other'},{name:'invalid-dimension',dimensions:0},{name:'invalid-id',id:'not-a-uuid'},{name:'negative-clock',now:-1},{name:'fractional-clock',now:1.5},{name:'passage-width',passage:'width'},{name:'passage-nonfinite',passage:'nan'},{name:'query-width',query:'width'},{name:'query-nonfinite',query:'nan'},{name:'open-fails',openFails:true},{name:'store-fails',storeFails:true},{name:'query-fails',queryFails:true},{name:'search-fails',searchFails:true},{name:'recall-miss',miss:true},{name:'audit-refused',auditFails:true},{name:'delete-fails',deleteFails:true},{name:'operation-and-audit-fail',queryFails:true,auditFails:true},{name:'operation-and-delete-fail',queryFails:true,deleteFails:true}];
async function run(){const out=[];for(const c of cases){const calls=[],rows=new Map();const request={expectedGeneration:'target-generation',fingerprint:{provider:'openai',model:'synthetic-target',dimensions:c.dimensions??3}};
 const probe=createGenerationRuntimeProbe({readActiveSelection:()=>({generation:c.active??'target-generation'}),createId:()=>c.id??'86db0fe4-922c-4ea2-9259-ea35ef10537d',now:()=>c.now??1234,
 embedTarget:async input=>{calls.push({kind:'embed',input});if(input.purpose==='query'&&c.queryFails)throw Error('synthetic query failed');const mode=c[input.purpose];return mode==='width'?[1,0]:mode==='nan'?[NaN,0,0]:[1,0,0];},
 withTargetDb:async(target,operation)=>{calls.push({kind:'open',target});if(c.openFails)throw Error('synthetic open failed');return operation({store:async row=>{calls.push({kind:'store',row});if(c.storeFails)throw Error('synthetic store failed');rows.set(row.id,row);},search:async(vector,limit,threshold)=>{calls.push({kind:'search',vector,limit,threshold});if(c.searchFails)throw Error('synthetic search failed');return c.miss?[]:[...rows.values()].map(entry=>({entry}));},delete:async id=>{calls.push({kind:'delete',id});if(c.deleteFails)throw Error('synthetic delete failed');rows.delete(id);}});},
 appendAudit:entry=>{calls.push({kind:'audit',entry});return !c.auditFails;}});
 let result;try{result={value:await probe(request)};}catch(e){result={error:e.message,aggregate:e instanceof AggregateError};}out.push({...c,request,...result,calls,remaining:[...rows.values()]});}return out;}
const recorded=await run();assert.deepEqual(await run(),recorded);writeFileSync(new URL('./golden/reembedding-runtime-probe.json',import.meta.url),JSON.stringify({recordedFrom:{engine:'node',source,node:process.version},cases:recorded},null,2)+'\n');console.log(`Recorded ${recorded.length} actual Node runtime probe cases twice`);
